export function normalizarLinha(linha) {
  if (typeof linha !== 'string') {
    throw new Error('linha precisa ser uma string');
  }

  const partes = linha.trim().split(' ');
  if (partes.length < 3) {
    throw new Error('linha malformada: ' + linha);
  }

  return {
    data: partes[0],
    hora: partes[1],
    nivel: partes[2],
    mensagem: partes.slice(3).join(' '),
  };
}

export function linhasParaEventos(texto) {
  if (typeof texto !== 'string') {
    throw new Error('texto precisa ser uma string');
  }

  return texto
    .split('\n')
    .filter((linha) => linha.trim() !== '')
    .map(normalizarLinha);
}

