export function contarPorNivel(eventos) {
  if (!Array.isArray(eventos)) {
    throw new Error('eventos precisa ser uma lista');
  }

  const contagem = {};
  for (const evento of eventos) {
    const nivel = evento.nivel;
    contagem[nivel] = (contagem[nivel] ?? 0) + 1;
  }
  return contagem;
}

export function contarErros(eventos) {
  if (!Array.isArray(eventos)) {
    throw new Error('eventos precisa ser uma lista');
  }

  return eventos.filter((evento) => evento.nivel === 'ERRO').length;
}

