import { linhasParaEventos } from './transformar.mjs';
import { contarPorNivel } from './agregar.mjs';

export function processarLog(texto, emissor) {
  if (!emissor || typeof emissor.emit !== 'function') {
    throw new Error('emissor precisa ter uma função emit');
  }

  const eventos = linhasParaEventos(texto);

  for (const evento of eventos) {
    emissor.emit('evento', evento);
  }

  return contarPorNivel(eventos);
}

