import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizarLinha, linhasParaEventos } from './lib/transformar.mjs';
import { contarPorNivel, contarErros } from './lib/agregar.mjs';
import { processarLog } from './lib/pipeline.mjs';

function criarEmissorFalso() {
  const emitidos = [];
  return {
    emit(nome, dado) {
      emitidos.push({ nome, dado });
    },
    emitidos,
  };
}

test('normalizarLinha separa os campos da linha', () => {
  const evento = normalizarLinha('2026-08-27 14:03:12 INFO Pedido 42 criado');
  assert.deepEqual(evento, {
    data: '2026-08-27',
    hora: '14:03:12',
    nivel: 'INFO',
    mensagem: 'Pedido 42 criado',
  });
});

test('linhasParaEventos processa o texto e ignora linhas vazias', () => {
  const eventos = linhasParaEventos('2026-08-27 14:03:12 INFO Pedido 42 criado\n\n2026-08-27 14:03:15 ERRO Falha no pagamento');
  assert.equal(eventos.length, 2);
  assert.equal(eventos[0].nivel, 'INFO');
  assert.equal(eventos[1].nivel, 'ERRO');
  assert.equal(eventos[1].mensagem, 'Falha no pagamento');
});

test('contarPorNivel soma as ocorrências de cada nível', () => {
  const eventos = [
    { nivel: 'INFO' },
    { nivel: 'ERRO' },
    { nivel: 'INFO' },
    { nivel: 'AVISO' },
  ];
  assert.deepEqual(contarPorNivel(eventos), { INFO: 2, ERRO: 1, AVISO: 1 });
  assert.deepEqual(contarPorNivel([]), {});
});

test('contarErros devolve só a quantidade de ERRO', () => {
  const eventos = [
    { nivel: 'INFO' },
    { nivel: 'ERRO' },
    { nivel: 'ERRO' },
  ];
  assert.equal(contarErros(eventos), 2);
  assert.equal(contarErros([]), 0);
});

test('processarLog transforma, agrega e emite um evento por linha', () => {
  const emissor = criarEmissorFalso();
  const texto = '2026-08-27 14:03:12 INFO Pedido 42 criado\n2026-08-27 14:03:15 ERRO Falha no pagamento';

  const resumo = processarLog(texto, emissor);

  assert.deepEqual(resumo, { INFO: 1, ERRO: 1 });
  assert.equal(emissor.emitidos.length, 2);
  assert.equal(emissor.emitidos[0].nome, 'evento');
  assert.equal(emissor.emitidos[0].dado.nivel, 'INFO');
  assert.equal(emissor.emitidos[1].dado.mensagem, 'Falha no pagamento');
});

test('processarLog lança erro quando o emissor não tem emit', () => {
  assert.throws(() => processarLog('2026-08-27 14:03:12 INFO ok', {}), /emit/);
});
